import logging
import re

from enum import Enum

from taf.ue.tm500.client.parser import RadioCard

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

rc_config_template = '''
#### BEGIN #######
RSET
ABOT 0 0 0
MULT 192.168.10.9
{rc_template}
GETR
SCFG {test_mode}
STRT
#### END #######
'''

radio_card_template = '''SCXT {load_context} {RAT}
SELR {radio_context} {chassis_number} {rc_card_name} {load_context} {interface_mode}
EREF {radio_context} {ref_in} {ref_out}
CFGR {radio_context} SCS {frequency_range} {subcarrier_spacing}
'''


class FrequencyRange(Enum):
    sub6ghz = 1
    above6ghz = 2

    def __str__(self):
        return str(self.value)


class SubCarrierSpacing(Enum):
    fifteenkhz = 0
    thirtykhz = 1
    onetwentykhz = 3

    def __str__(self):
        return str(self.value)


class TMARadioCard(object):
    """Class containing all values to configure a TMA Radio card"""

    def __init__(self, radiocard, clk_ref_in=False, clk_ref_out=True, interface_mode="COMBINED",
                 frequency_range=FrequencyRange.sub6ghz, subcarrier_spacing=SubCarrierSpacing.thirtykhz):
        """

        :param radiocard: object of the type parser.RadioCard
        :param clk_ref_in: Enable/Disable external frequency input reference clock
        :param clk_ref_out: Enable/Disable external frequency output reference clock
        :param interface_mode: Interface to the outside world
        :param frequency_range: Frequency range category
        :param subcarrier_spacing: Base subcarrier spacing
        """

        self.radiocard = radiocard
        self.load = re.findall(r'\b[A-Z]+\b', radiocard.load)[-1]
        self.load_context = radiocard.load.split()[0]
        self.clk_ref_in = int(clk_ref_in)
        self.clk_ref_out = int(clk_ref_out)
        self.interface_mode = interface_mode
        self.frequency_range = FrequencyRange(frequency_range)
        self.subcarrier_spacing = SubCarrierSpacing(subcarrier_spacing)

    def __setattr__(self, name, value):
        if name == 'radiocard' and not isinstance(value, RadioCard):
            raise TypeError('radiocard must be of the type parser.RadioCard')
        super(TMARadioCard, self).__setattr__(name, value)


class RadioCardConfigScript(object):
    """TMA script for TM500 radio card configuration"""

    def __init__(self, tma_radio_cards_list, test_mode='NAS_MODE'):
        """

        :param tma_radio_cards_list: list of TMARadioCard objects
        :param test_mode: configuration test mode for TMA
        """
        self.rc_list = tma_radio_cards_list
        self.test_mode = test_mode

    def __str__(self):
        return rc_config_template.format(rc_template=self.generate_radio_cards(),
                                         test_mode=self.test_mode)

    def generate_radio_cards(self):
        script = ""
        for rc in self.rc_list:
            script += radio_card_template.format(load_context=rc.load_context,
                                                 RAT=rc.load,
                                                 radio_context=rc.radiocard.context,
                                                 chassis_number=rc.radiocard.chassis,
                                                 rc_card_name=rc.radiocard.slot,
                                                 interface_mode=rc.interface_mode,
                                                 ref_in=rc.clk_ref_in,
                                                 ref_out=rc.clk_ref_out,
                                                 frequency_range=rc.frequency_range,
                                                 subcarrier_spacing=rc.subcarrier_spacing
                                                 )
        return script
